insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1727','braille','Braille writing','medium','classic','When using a traditional slate and stylus, in which direction is the text commonly written on the reverse side of the paper?','["From right to left","From left to right","From bottom to top","In a circle"]'::jsonb,'From right to left','With a conventional slate and stylus, the writer punches reversed cells from right to left so they read correctly when the paper is turned over.',10,2,array['braille writing'],'en',true,'BANA, The ABCs of UEB — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; Government of India/NIEPVD, Standard Bharati Braille Codes — https://cdnbbsr.s3waas.gov.in/s36ee69d3769e832ec77c9584e0b7ba112/uploads/2025/01/20250104954295710.pdf') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1728','braille','Braille literacy','easy','classic','What makes Braille characters readable by touch?','["Raised dot patterns","Different printed colors","Scented ink","Magnetic sounds"]'::jsonb,'Raised dot patterns','Braille is a tactile writing system in which raised dots can be read by touch.',10,2,array['braille literacy'],'en',true,'BANA, The ABCs of UEB — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; Government of India/NIEPVD, Standard Bharati Braille Codes — https://cdnbbsr.s3waas.gov.in/s36ee69d3769e832ec77c9584e0b7ba112/uploads/2025/01/20250104954295710.pdf') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1729','braille','Braille literacy','medium','classic','Is Braille itself a spoken language?','["No, it is a tactile code used to represent written language","Yes, it is spoken only by computers","Yes, it is a language with no written form","No, it is a type of musical instrument"]'::jsonb,'No, it is a tactile code used to represent written language','Braille is a writing system or code; it represents languages rather than being a language by itself.',10,2,array['braille literacy'],'en',true,'BANA, The ABCs of UEB — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; Government of India/NIEPVD, Standard Bharati Braille Codes — https://cdnbbsr.s3waas.gov.in/s36ee69d3769e832ec77c9584e0b7ba112/uploads/2025/01/20250104954295710.pdf') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1730','braille','Braille literacy','medium','classic','What is Braille music notation used to represent?','["Musical information such as notes and rhythms","Only the names of music venues","The volume setting on a radio","A map of an orchestra stage"]'::jsonb,'Musical information such as notes and rhythms','Braille music notation is a specialized code for reading and writing musical information by touch.',10,2,array['braille literacy'],'en',true,'BANA, The ABCs of UEB — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; Government of India/NIEPVD, Standard Bharati Braille Codes — https://cdnbbsr.s3waas.gov.in/s36ee69d3769e832ec77c9584e0b7ba112/uploads/2025/01/20250104954295710.pdf') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1731','braille','Braille basics','easy','classic','How are dot positions numbered in the left column of a six-dot cell?','["From 1 at the top to 3 at the bottom","From 3 at the top to 1 at the bottom","From 4 at the top to 6 at the bottom","From 6 at the top to 4 at the bottom"]'::jsonb,'From 1 at the top to 3 at the bottom','The left-column dots are numbered 1 at the top, 2 in the middle, and 3 at the bottom.',10,2,array['braille basics'],'en',true,'BANA, The ABCs of UEB — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; Government of India/NIEPVD, Standard Bharati Braille Codes — https://cdnbbsr.s3waas.gov.in/s36ee69d3769e832ec77c9584e0b7ba112/uploads/2025/01/20250104954295710.pdf') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1732','braille','Braille tools','medium','classic','What is the usual purpose of a Braille label on a household item?','["To let a reader identify information by touch","To make the item produce speech","To change the item''s color","To prevent the item from being opened"]'::jsonb,'To let a reader identify information by touch','A Braille label makes written information on an item accessible by touch.',10,2,array['braille tools'],'en',true,'BANA, The ABCs of UEB — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; Government of India/NIEPVD, Standard Bharati Braille Codes — https://cdnbbsr.s3waas.gov.in/s36ee69d3769e832ec77c9584e0b7ba112/uploads/2025/01/20250104954295710.pdf') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1733','braille','Braille literacy','medium','classic','Why can punctuation signs matter in Braille just as they do in print?','["They help show sentence structure and meaning","They always identify the writer''s age","They replace every letter in a word","They determine the paper''s thickness"]'::jsonb,'They help show sentence structure and meaning','Punctuation helps a reader understand sentence boundaries, questions, quotations, and other aspects of written meaning.',10,2,array['braille literacy'],'en',true,'BANA, The ABCs of UEB — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; Government of India/NIEPVD, Standard Bharati Braille Codes — https://cdnbbsr.s3waas.gov.in/s36ee69d3769e832ec77c9584e0b7ba112/uploads/2025/01/20250104954295710.pdf') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1734','braille','Braille tools','medium','classic','What is one advantage of a refreshable Braille display connected to a computer?','["It can present changing text from the computer","It prints permanent ink on every page","It automatically corrects every written fact","It enlarges the computer monitor physically"]'::jsonb,'It can present changing text from the computer','A refreshable display can render changing screen text as tactile Braille rather than requiring a separate embossed page for each screen.',10,2,array['braille tools'],'en',true,'BANA, The ABCs of UEB — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; Government of India/NIEPVD, Standard Bharati Braille Codes — https://cdnbbsr.s3waas.gov.in/s36ee69d3769e832ec77c9584e0b7ba112/uploads/2025/01/20250104954295710.pdf') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
