insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1782','accounting','Equity','medium','classic','What are retained earnings?','["Accumulated profits kept in the business, less distributions and other adjustments","Amounts customers still owe","Cash borrowed from a supplier","The cost of every product sold in one day"]'::jsonb,'Accumulated profits kept in the business, less distributions and other adjustments','Retained earnings represent accumulated net income retained in equity, adjusted for distributions and other items.',10,2,array['equity'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
