insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1785','accounting','Accruals','medium','classic','What accounting term describes a cost incurred but not yet paid?','["A cost recognized before it has been paid","A customer payment received before a sale","A product returned to a supplier","A long-term investment that earns a dividend"]'::jsonb,'A cost recognized before it has been paid','An accrued expense is recognized when incurred even though payment will occur later.',10,2,array['accruals'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1786','accounting','Inventory','medium','classic','What does FIFO mean as an inventory cost-flow assumption?','["First in, first out","Final invoice, final order","Fixed interest, fixed output","Financial information for operations"]'::jsonb,'First in, first out','FIFO assumes that the earliest costs are assigned to goods sold first, subject to the applicable accounting framework.',10,2,array['inventory'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
