insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1949','birds','Bird anatomy','hard','classic','What does the uropygial gland produce in many birds?','["An oily secretion used during feather care","The calcium shell around an egg","A liquid that digests seeds in the crop","A pigment that makes bones hollow"]'::jsonb,'An oily secretion used during feather care','Many birds spread oil from the uropygial gland while preening, though its functions vary by species.',10,2,array['bird anatomy'],'en',true,'Cornell Lab of Ornithology, All About Birds — https://www.allaboutbirds.org/guide/') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
