insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2123','civics','Government','medium','classic','What does due process generally require?','["Fair procedures before government deprives a person of a protected right","A rule that every court case must end in a fine","A guarantee that every legal claim will succeed","A system in which laws apply only to citizens"]'::jsonb,'Fair procedures before government deprives a person of a protected right','Due process refers to legally required fair procedures, with details set by each legal system.',10,2,array['government'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2124','civics','Elections','medium','classic','What is proportional representation intended to do in an election?','["Allocate seats in a way that broadly reflects votes received","Let courts appoint every representative","Require every voter to support two candidates","End the need to count ballots"]'::jsonb,'Allocate seats in a way that broadly reflects votes received','Proportional representation systems aim to make representation broadly correspond to votes, according to their rules.',10,2,array['elections'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2125','civics','Government','hard','classic','What is a filibuster in some legislative systems?','["A procedural tactic used to delay or block a vote, often by extending debate","A court order that cancels an election","A public petition signed by legislators","A committee report that automatically becomes law"]'::jsonb,'A procedural tactic used to delay or block a vote, often by extending debate','A filibuster is a procedural tactic—often involving prolonged debate—used in some legislatures to delay or prevent a vote.',10,2,array['government'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2126','civics','Government','medium','classic','Why are checks and balances used in government?','["To limit the concentration of power among branches or institutions","To make every public decision unanimous","To prevent legislatures from debating laws","To let one branch control all public offices"]'::jsonb,'To limit the concentration of power among branches or institutions','Checks and balances allow institutions to limit or review one another''s powers.',10,2,array['government'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2127','civics','Government','medium','classic','What does a census count?','["The population and related characteristics of a country or area","Only the number of government buildings","The number of laws passed in a day","The results of a court appeal"]'::jsonb,'The population and related characteristics of a country or area','A census systematically counts a population and gathers information about it.',10,2,array['government'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2128','civics','Government','medium','classic','What is an executive order?','["A directive issued by an executive authority to guide government operations","A final judgment issued by an appellate court","A formal change made to a constitution","A request asking a public authority to consider an issue"]'::jsonb,'A directive issued by an executive authority to guide government operations','An executive order is a directive from an executive branch authority; its scope and legal effect depend on the jurisdiction and applicable law.',10,2,array['government'],'en',true,'Constitution of India — https://legislative.gov.in/constitution-of-india/ ; UN Human Rights — https://www.ohchr.org/en/human-rights/universal-declaration/translations/english') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
