insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2174','music','Notation','hard','classic','What is an accidental in music notation?','["A sign that raises, lowers, or restores a note''s pitch","A symbol that changes the instrument''s size","A mark that indicates a singer''s language","A note that has no fixed pitch"]'::jsonb,'A sign that raises, lowers, or restores a note''s pitch','Accidentals alter a note from the pitch indicated by the key signature.',10,2,array['notation'],'en',true,'Open Music Theory — https://viva.pressbooks.pub/openmusictheory/') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
