insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2236','braille','Braille literacy','hard','classic','What can a Braille page indicator help a reader keep track of?','["A page''s position in a longer text","The reader''s typing speed","The temperature of the paper","The number of voices in an audio recording"]'::jsonb,'A page''s position in a longer text','Page indicators help readers navigate the sequence of pages in a longer Braille work.',10,2,array['braille literacy'],'en',true,'Braille Authority of North America (BANA), UEB and Nemeth codebooks, Music Braille Code, tactile-graphics manual, and slate-and-stylus guidance — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; https://www.brailleauthority.org/nemeth-code ; https://brailleauthority.org/music-braille-code ; https://www.brailleauthority.org/tg/web-manual/tgmanual.html ; https://www.brailleauthority.org/slatestylus/slate.pdf ; American Printing House, Refreshabraille user guide (cursor routing and display controls) — https://tech.aph.org/rbd_doc.htm ; Unicode Braille Patterns chart — https://www.unicode.org/charts/PDF/U2800.pdf') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2237','management','Projects','easy','classic','What is a project deliverable?','["A specific output or result produced by project work","A meeting held before a project begins","The person who approves every employee''s leave","A list of possible project risks only"]'::jsonb,'A specific output or result produced by project work','A deliverable is a verifiable output or result that a project is expected to produce.',10,2,array['projects'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2238','management','Projects','medium','classic','What is a project charter used to do?','["Formally authorize a project and state its high-level purpose and boundaries","Record every daily transaction made by a company","Schedule annual leave for an entire department","Describe the personal preferences of each customer"]'::jsonb,'Formally authorize a project and state its high-level purpose and boundaries','A project charter formally authorizes work and records high-level information such as purpose, objectives, and boundaries.',10,2,array['projects'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2239','management','Teams','medium','classic','What does a project sponsor typically do?','["Champions the project and provides high-level support or authorization","Performs every task assigned to the project team","Audits every customer’s personal account","Sets the market price of the project’s output"]'::jsonb,'Champions the project and provides high-level support or authorization','A project sponsor supports and advocates for a project and may provide authorization, resources, or senior-level guidance.',10,2,array['teams'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2240','management','Projects','medium','classic','What is a task dependency in a project schedule?','["A relationship that determines the order in which activities can occur","A record of the money already spent","A measure of employee satisfaction","A list of customers who have made a purchase"]'::jsonb,'A relationship that determines the order in which activities can occur','A task dependency links activities so that the timing or completion of one can affect another.',10,2,array['projects'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
