insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2249','management','Quality','medium','classic','What is a pilot test used for before a wider rollout?','["Trying a process or product on a limited scale to find issues","Approving every final product without inspection","Replacing all project planning with a survey","Measuring a company’s annual tax rate"]'::jsonb,'Trying a process or product on a limited scale to find issues','A pilot test tries an approach with a limited group or setting so problems can be found before broader use.',10,2,array['quality'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
