insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2251','management','Decision-making','medium','classic','What does a decision tree help a team analyze?','["Choices and their possible outcomes or consequences","The reporting relationships in a matrix organization","The timing of every meeting in a month","The number of units held in a warehouse"]'::jsonb,'Choices and their possible outcomes or consequences','A decision tree maps choices and possible outcomes to help compare options under uncertainty.',10,2,array['decision-making'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
