insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2277','accounting','Statements','medium','classic','What does a statement of changes in equity report?','["Changes in owners’ equity over a reporting period","Only the cash held by a business on one date","The number of products sold by each employee","The amount of tax charged on every invoice"]'::jsonb,'Changes in owners’ equity over a reporting period','A statement of changes in equity reconciles opening and closing equity and reports movements during the period.',10,2,array['statements'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2278','accounting','Accounts','hard','classic','What is a contra-asset account?','["An account that reduces the reported amount of a related asset","An account used only to record sales tax","A record of customer satisfaction scores","An account that increases every liability"]'::jsonb,'An account that reduces the reported amount of a related asset','Accumulated depreciation is an example of a contra-asset that offsets a related asset balance.',10,2,array['accounts'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2279','accounting','Reporting','medium','classic','What is an accounting estimate?','["An approximate amount based on available evidence when exact measurement is not possible","A receipt that proves a customer paid in cash","A list of all transactions entered into a journal","A rule that every asset must be sold at its original price"]'::jsonb,'An approximate amount based on available evidence when exact measurement is not possible','Accounting estimates use reasonable information and judgment to measure amounts that cannot be observed precisely.',10,2,array['reporting'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2280','accounting','Records','hard','classic','What is a subsidiary ledger used for?','["Keeping detailed records that support a related general-ledger balance","Recording only a company’s annual profit","Listing the names of shareholders in order of age","Setting the market price of a company’s shares"]'::jsonb,'Keeping detailed records that support a related general-ledger balance','A subsidiary ledger contains details—such as individual customer balances—that support a summarized general-ledger account.',10,2,array['records'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2281','accounting','Methods','medium','classic','What does cash-basis accounting generally record?','["Income when cash is received and expenses when cash is paid","Income only when a contract is signed","Every asset at its future selling price","Transactions only at the end of a company’s financial year"]'::jsonb,'Income when cash is received and expenses when cash is paid','Under cash-basis accounting, income and expenses are generally recorded when cash is received or paid, subject to applicable rules.',10,2,array['methods'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2282','accounting','Accounts','medium','classic','What is a suspense account used for?','["Temporarily holding an amount whose correct account or treatment has not yet been determined","Recording only cash received from customers","Tracking the market price of company shares","Storing the list of a company’s products"]'::jsonb,'Temporarily holding an amount whose correct account or treatment has not yet been determined','A suspense account temporarily holds an entry while its correct classification or cause is investigated.',10,2,array['accounts'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2283','accounting','Accounts','medium','classic','What is a current liability?','["An obligation expected to be settled in the operating cycle or within a year","A resource expected to provide future benefits","A payment made only by customers","An asset that cannot be sold"]'::jsonb,'An obligation expected to be settled in the operating cycle or within a year','Current liabilities are generally due within the operating cycle or twelve months, depending on the reporting framework.',10,2,array['accounts'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2284','accounting','Records','medium','classic','What is an adjusting entry in accounting?','["An entry made at the end of a period to update accounts before financial statements are prepared","A purchase request sent to a supplier","A record of a customer’s card payment at checkout","A transfer of every balance-sheet amount into cash"]'::jsonb,'An entry made at the end of a period to update accounts before financial statements are prepared','Adjusting entries update account balances for items such as accrued or prepaid amounts before statements are prepared.',10,2,array['records'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2285','accounting','Accounts','medium','classic','What is unearned revenue?','["Payment received before the related goods or services have been provided","A bill a business has not yet paid to a supplier","An amount a customer owes for a completed sale","A reduction in the value of equipment over time"]'::jsonb,'Payment received before the related goods or services have been provided','Unearned revenue is generally recorded as a liability until the promised goods or services are provided.',10,2,array['accounts'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2286','accounting','Reporting','hard','classic','What is a deferred tax asset?','["A future tax benefit arising from deductible temporary differences or similar items","Cash set aside to pay a supplier tomorrow","A machine that will be used to produce goods","A loan that a company has already repaid"]'::jsonb,'A future tax benefit arising from deductible temporary differences or similar items','A deferred tax asset represents tax amounts that may reduce future tax payments, subject to recognition requirements.',10,2,array['reporting'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2287','accounting','Methods','medium','classic','What does accrual-basis accounting generally record?','["Transactions when income is earned or expenses are incurred","Every transaction only when cash changes hands","Only sales made at the end of a year","Only purchases paid for with a card"]'::jsonb,'Transactions when income is earned or expenses are incurred','Accrual accounting recognizes revenues when earned and expenses when incurred, subject to applicable rules.',10,2,array['methods'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2288','accounting','Records','medium','classic','What is an audit trail?','["A sequence of records that allows a transaction to be traced through a system","A forecast of future exchange rates","A list of employees who attended a meeting","A schedule for replacing office equipment"]'::jsonb,'A sequence of records that allows a transaction to be traced through a system','An audit trail links supporting records and system activity so transactions can be followed and checked.',10,2,array['records'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2289','accounting','Methods','hard','classic','What is a reversing entry in accounting?','["An entry in a new period that reverses a specified prior-period adjustment","A record that lists goods packed into a shipment","A document showing a company’s market share","A payment made to acquire a competitor"]'::jsonb,'An entry in a new period that reverses a specified prior-period adjustment','Some prior-period adjusting entries are reversed at the start of a new period to simplify recording related transactions.',10,2,array['methods'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2290','accounting','Reporting','hard','classic','Under IFRS, when is an impairment loss generally recognized for an asset?','["When its carrying amount exceeds its recoverable amount","When the asset is purchased for cash","When revenue is received before a service is provided","When a company pays a dividend to shareholders"]'::jsonb,'When its carrying amount exceeds its recoverable amount','Under IFRS, an impairment loss is recognized when an asset’s carrying amount exceeds its recoverable amount.',10,2,array['reporting'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2291','accounting','Equity','medium','classic','What is a share buyback?','["When a company repurchases its own shares","When a customer returns a product to a shop","When a lender reduces a loan''s interest rate","When a firm issues a new product catalogue"]'::jsonb,'When a company repurchases its own shares','A share buyback occurs when a company purchases its own shares, subject to applicable rules.',10,2,array['equity'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2292','accounting','Methods','hard','classic','What is the matching principle in traditional accounting terminology?','["Recognizing related expenses in the period of the revenues they help generate","Recording every asset at its future selling price","Matching each employee with a customer","Making every balance sheet have two pages"]'::jsonb,'Recognizing related expenses in the period of the revenues they help generate','The matching principle associates expenses with the revenues they help produce, within the reporting framework.',10,2,array['methods'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2293','accounting','Accounts','hard','classic','What is an intangible asset?','["A non-physical resource such as a patent or software right","Cash held in a bank account","A machine used in production","A building owned by the business"]'::jsonb,'A non-physical resource such as a patent or software right','Intangible assets lack physical substance and may include identifiable rights such as patents.',10,2,array['accounts'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2294','accounting','Statements','hard','classic','What does liquidity describe for a business?','["Its ability to meet short-term obligations as they fall due","The number of products made each day","The long-term popularity of a brand","The number of offices a business operates"]'::jsonb,'Its ability to meet short-term obligations as they fall due','Liquidity is the ability to meet obligations as they become due, often using readily available resources.',10,2,array['statements'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2295','accounting','Methods','hard','classic','What does revenue recognition address?','["When and how revenue is recorded in financial statements","The order in which customers enter a shop","How a company chooses a logo color","The method for calculating an employee''s commute"]'::jsonb,'When and how revenue is recorded in financial statements','Revenue recognition principles determine when and how an entity records income from contracts with customers.',10,2,array['methods'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2296','accounting','Reporting','hard','classic','What does other comprehensive income include?','["Certain gains and losses reported outside profit or loss under accounting standards","All cash received from customers during a period","Every expense paid before a reporting date","Only dividends paid to shareholders"]'::jsonb,'Certain gains and losses reported outside profit or loss under accounting standards','Other comprehensive income includes specified gains and losses that accounting standards present separately from profit or loss within comprehensive income.',10,2,array['reporting'],'en',true,'IFRS Foundation, issued standards — https://www.ifrs.org/issued-standards/list-of-standards/ ; IAASB standards — https://www.iaasb.org/publications') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2297','commerce','Trade documents','easy','classic','What is a commercial invoice used for in international trade?','["It lists goods sold and details such as price and buyer","It proves a ship has been repaired","It sets the exchange rate for a country","It replaces the need to pack goods"]'::jsonb,'It lists goods sold and details such as price and buyer','A commercial invoice describes a sale and is used in trade and customs documentation.',10,2,array['trade documents'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2298','commerce','Trade documents','medium','classic','What does a bill of lading commonly serve as?','["A receipt for shipped goods and evidence of the carriage contract","A certificate that goods are tax-free everywhere","A retail price tag for a product","A bank statement for the ship''s crew"]'::jsonb,'A receipt for shipped goods and evidence of the carriage contract','A bill of lading can serve as a receipt, evidence of a contract of carriage, and in some cases a document of title.',10,2,array['trade documents'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2299','commerce','Logistics','medium','classic','What is a bonded warehouse?','["A customs-controlled facility where imported goods may be stored before applicable duties are paid","A shop that sells only goods made locally","A shipper’s document listing the contents of every package","A market where buyers bid on used machinery"]'::jsonb,'A customs-controlled facility where imported goods may be stored before applicable duties are paid','A bonded warehouse stores goods under customs control, often allowing duties to be deferred until release.',10,2,array['logistics'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2300','commerce','Trade rules','medium','classic','What do Incoterms rules mainly clarify in a sale of goods?','["Certain delivery responsibilities, costs, and risks between seller and buyer","The quality grade of every product","The exchange rate used by all banks","The language that must appear on an invoice"]'::jsonb,'Certain delivery responsibilities, costs, and risks between seller and buyer','Incoterms allocate specified obligations, costs, and risks in delivery between parties to a sale.',10,2,array['trade rules'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2301','commerce','Logistics','medium','classic','What does a customs broker help an importer do?','["Prepare customs documentation and arrange clearance under local rules","Set the global price of a product","Insure every shipment without a contract","Manufacture a shipping container"]'::jsonb,'Prepare customs documentation and arrange clearance under local rules','Customs brokers help prepare declarations and coordinate clearance with customs authorities.',10,2,array['logistics'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2302','commerce','Trade rules','hard','classic','When may an exporter need an export licence?','["When regulations require authorization for certain goods, destinations, or end uses","Whenever a package is sent to another city","Only when a buyer pays in cash","Whenever a company prints a commercial invoice"]'::jsonb,'When regulations require authorization for certain goods, destinations, or end uses','Export controls may require a licence for particular products, destinations, end users, or uses; the applicable rules depend on jurisdiction.',10,2,array['trade rules'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2303','commerce','Trade rules','medium','classic','What does a customs union generally establish among its members?','["Free trade among members and a common external tariff on many imports","A shared currency and one central bank in every case","A rule that all exports must be sold at the same price","A ban on trade with every neighboring country"]'::jsonb,'Free trade among members and a common external tariff on many imports','A customs union removes many trade barriers among members and applies a common external tariff to goods from outside the union.',10,2,array['trade rules'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2304','commerce','Logistics','medium','classic','What does containerization mean in freight transport?','["Moving goods in standardized reusable containers","Wrapping every parcel in paper","Sending products only by air","Storing all goods in a retail display"]'::jsonb,'Moving goods in standardized reusable containers','Containerization uses standardized containers that can be transferred between transport modes.',10,2,array['logistics'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2305','commerce','Trade documents','medium','classic','What is a pro forma invoice?','["A preliminary document outlining a proposed sale before the final invoice","A final court judgment about a shipment","A receipt showing that customs duty was paid","A certificate proving a product has been sold at retail"]'::jsonb,'A preliminary document outlining a proposed sale before the final invoice','A pro forma invoice gives a preliminary description and estimated value of a proposed transaction.',10,2,array['trade documents'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2306','commerce','Trade rules','hard','classic','What is the Harmonized System used for in international trade?','["Classifying traded products with standardized codes","Measuring the distance a ship travels","Setting the price of every exported product","Recording a company''s annual sales"]'::jsonb,'Classifying traded products with standardized codes','The Harmonized System is an international nomenclature for classifying traded products.',10,2,array['trade rules'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2307','commerce','Logistics','medium','classic','What does demurrage commonly charge for in container shipping?','["Keeping a container at a port terminal beyond the allowed free time","Returning an empty container before its due date","Insuring cargo against damage during a voyage","Moving goods from a warehouse to a local shop"]'::jsonb,'Keeping a container at a port terminal beyond the allowed free time','Demurrage commonly refers to charges when a container remains at a terminal beyond its permitted free time.',10,2,array['logistics'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2308','commerce','Logistics','medium','classic','What is an advance shipping notice used to communicate?','["Details about an upcoming shipment before it arrives","The final profit made by the carrier","The design of a product’s retail package","The exchange rate used to pay a supplier"]'::jsonb,'Details about an upcoming shipment before it arrives','An advance shipping notice gives a receiver information about a shipment before delivery, such as its contents and expected arrival.',10,2,array['logistics'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2309','commerce','Payments','medium','classic','What is a chargeback in card payments?','["A reversal of a card transaction initiated through the cardholder’s bank, often after a dispute","A discount applied automatically to every cash purchase","A fee paid to ship goods across a border","A statement showing how much stock remains in a shop"]'::jsonb,'A reversal of a card transaction initiated through the cardholder’s bank, often after a dispute','A chargeback reverses a card payment through the payment system, commonly following a dispute.',10,2,array['payments'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2310','commerce','Retail','medium','classic','What is an online marketplace?','["A platform where multiple sellers can offer goods or services to buyers","A customs warehouse that stores only one company''s goods","A bank account used only for international tax","A paper catalogue printed once a year"]'::jsonb,'A platform where multiple sellers can offer goods or services to buyers','An online marketplace connects buyers with offerings from multiple sellers.',10,2,array['retail'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2311','commerce','E-commerce','medium','classic','What is drop shipping?','["A retailer forwards an order to a supplier that ships directly to the customer","A carrier moves goods back to a factory for recycling","A customer pays a fee to collect a package","A warehouse transfers freight between two trucks"]'::jsonb,'A retailer forwards an order to a supplier that ships directly to the customer','In drop shipping, the retailer sells an item while a supplier or third party fulfills the shipment directly.',10,2,array['e-commerce'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2312','commerce','Payments','hard','classic','What is documentary collection in trade finance?','["Banks handle shipping documents against payment or a payment promise","A method that makes every export free of risk","A shipment paid for only with coins","A government grant that reimburses customs fees"]'::jsonb,'Banks handle shipping documents against payment or a payment promise','In documentary collection, banks transfer documents according to the seller''s instructions, often against payment or acceptance.',10,2,array['payments'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2313','commerce','Trade documents','medium','classic','What does a certificate of conformity generally attest?','["That a product meets specified standards or regulatory requirements","The country where the product was first sold","The route a cargo ship followed","The exact date a buyer made payment"]'::jsonb,'That a product meets specified standards or regulatory requirements','A certificate of conformity provides evidence that a product meets stated requirements or standards.',10,2,array['trade documents'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2314','commerce','Logistics','hard','classic','What is cross-docking in logistics?','["Transferring incoming goods to outbound transport with little storage","Keeping every shipment in a warehouse for a full year","Sending an empty container back to its manufacturer","Delivering a product only to a border checkpoint"]'::jsonb,'Transferring incoming goods to outbound transport with little storage','Cross-docking moves goods from receiving to shipping with minimal time in storage.',10,2,array['logistics'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2315','commerce','Trade','hard','classic','What is a trade facilitation measure intended to do?','["Simplify and speed up legitimate cross-border trade procedures","Prevent all goods from crossing borders","Require every exporter to use one shipping company","Set a single retail price worldwide"]'::jsonb,'Simplify and speed up legitimate cross-border trade procedures','Trade facilitation seeks to simplify, modernize, and harmonize import and export procedures.',10,2,array['trade'],'en',true,'International Trade Centre SME Trade Academy and WTO glossary — https://learning.intracen.org/ ; https://www.wto.org/english/thewto_e/glossary_e/glossary_e.htm') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
