insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2439','health','Community health','medium','classic','What are social determinants of health?','["Conditions in the places where people live, learn, work, and age","Only the genes inherited from parents","A list of medicines in a pharmacy","The number of hospitals in one city"]'::jsonb,'Conditions in the places where people live, learn, work, and age','Social determinants include conditions such as housing, education, work, and community resources.',10,2,array['community health'],'en',true,'MedlinePlus Health Topics — https://medlineplus.gov/healthtopics.html ; Centers for Disease Control and Prevention — https://www.cdc.gov/') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2440','health','Prevention','easy','classic','What is primary prevention intended to do?','["Reduce the chance that a disease or injury occurs","Treat complications after they have developed","Record a patient''s height after a visit","Replace emergency care in every situation"]'::jsonb,'Reduce the chance that a disease or injury occurs','Primary prevention aims to prevent a condition before it occurs, for example through vaccination or safer environments.',10,2,array['prevention'],'en',true,'MedlinePlus Health Topics — https://medlineplus.gov/healthtopics.html ; Centers for Disease Control and Prevention — https://www.cdc.gov/') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
