insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2450','health','Community health','medium','classic','What is a noncommunicable disease?','["A condition that is not transmitted directly from one person to another","A disease that affects only one person worldwide","An illness caused only by bacteria","A condition that has no risk factors"]'::jsonb,'A condition that is not transmitted directly from one person to another','Noncommunicable diseases do not spread directly from person to person, though many have complex causes.',10,2,array['community health'],'en',true,'MedlinePlus Health Topics — https://medlineplus.gov/healthtopics.html ; Centers for Disease Control and Prevention — https://www.cdc.gov/') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2451','health','Everyday health','easy','classic','What is first aid?','["Immediate assistance given to someone who is injured or suddenly ill","A long-term treatment plan written by a specialist","A method for measuring a country''s population","A way to replace professional emergency services"]'::jsonb,'Immediate assistance given to someone who is injured or suddenly ill','First aid is initial help provided until professional care is available or the person recovers.',10,2,array['everyday health'],'en',true,'MedlinePlus Health Topics — https://medlineplus.gov/healthtopics.html ; Centers for Disease Control and Prevention — https://www.cdc.gov/') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
