insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2453','health','Mental well-being','medium','classic','What is one purpose of a relaxation technique such as slow breathing?','["To support calm and manage stress in the moment","To diagnose every mental health condition","To replace all forms of professional care","To ensure that stressful events never happen"]'::jsonb,'To support calm and manage stress in the moment','Relaxation strategies can help some people manage momentary stress, though they are not a substitute for needed care.',10,2,array['mental well-being'],'en',true,'MedlinePlus Health Topics — https://medlineplus.gov/healthtopics.html ; Centers for Disease Control and Prevention — https://www.cdc.gov/') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2454','health','Community health','hard','classic','What does health equity aim to promote?','["Fair opportunities for everyone to achieve their best possible health","Identical health outcomes for every person","The same medical treatment regardless of need","Health services only in large cities"]'::jsonb,'Fair opportunities for everyone to achieve their best possible health','Health equity seeks fair opportunity by addressing avoidable barriers and differences in conditions.',10,2,array['community health'],'en',true,'MedlinePlus Health Topics — https://medlineplus.gov/healthtopics.html ; Centers for Disease Control and Prevention — https://www.cdc.gov/') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2455','health','Everyday health','hard','classic','What does informed consent involve?','["Understanding relevant information and voluntarily agreeing to a procedure or study","Signing any form without an explanation","Allowing someone else to decide without discussion","Guaranteeing that a treatment will succeed"]'::jsonb,'Understanding relevant information and voluntarily agreeing to a procedure or study','Informed consent involves understandable information, capacity, and a voluntary choice, subject to applicable rules.',10,2,array['everyday health'],'en',true,'MedlinePlus Health Topics — https://medlineplus.gov/healthtopics.html ; Centers for Disease Control and Prevention — https://www.cdc.gov/') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
