insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2470','literature','Genres','medium','classic','What is an epistolary novel?','["A novel told through documents such as letters, diary entries, or messages","A poem that has exactly fourteen lines","A play written only as stage directions","A story that contains no narrator"]'::jsonb,'A novel told through documents such as letters, diary entries, or messages','An epistolary novel presents its narrative through documents such as letters or diary entries.',10,2,array['genres'],'en',true,'Encyclopaedia Britannica literature and author biographies — https://www.britannica.com/art/literature ; Nobel Prize, Rabindranath Tagore — https://www.nobelprize.org/prizes/literature/1913/tagore/') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2471','literature','Genres','medium','classic','How does a memoir generally differ from a full autobiography?','["A memoir focuses on selected experiences or themes from the author''s life","A memoir is always written by a friend","An autobiography can contain no personal memories","A memoir is a fictional play"]'::jsonb,'A memoir focuses on selected experiences or themes from the author''s life','Memoirs usually focus on particular experiences or themes rather than covering an entire life.',10,2,array['genres'],'en',true,'Encyclopaedia Britannica literature and author biographies — https://www.britannica.com/art/literature ; Nobel Prize, Rabindranath Tagore — https://www.nobelprize.org/prizes/literature/1913/tagore/') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2472','literature','Storytelling','medium','classic','What is dramatic irony?','["The audience knows something important that a character does not","A character tells a joke during every scene","A story has no ending","A play contains only songs"]'::jsonb,'The audience knows something important that a character does not','Dramatic irony occurs when the audience has information that a character lacks.',10,2,array['storytelling'],'en',true,'Encyclopaedia Britannica literature and author biographies — https://www.britannica.com/art/literature ; Nobel Prize, Rabindranath Tagore — https://www.nobelprize.org/prizes/literature/1913/tagore/') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
