insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2474','literature','Poetry','medium','classic','What is an allusion in literature?','["A brief reference to a person, event, or work outside the text","A full summary printed at the end of every chapter","A repeated rhyme at the end of each stanza","A word that imitates a sound"]'::jsonb,'A brief reference to a person, event, or work outside the text','An allusion indirectly refers to a well-known person, event, text, or idea.',10,2,array['poetry'],'en',true,'Encyclopaedia Britannica literature and author biographies — https://www.britannica.com/art/literature ; Nobel Prize, Rabindranath Tagore — https://www.nobelprize.org/prizes/literature/1913/tagore/') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2475','literature','Drama','medium','classic','What is a stage direction in a play?','["An instruction about movement, setting, sound, or performance","A speech delivered by the audience","A list of books sold at the theatre","A poem printed before the title page"]'::jsonb,'An instruction about movement, setting, sound, or performance','Stage directions guide performance details and are usually distinct from spoken dialogue.',10,2,array['drama'],'en',true,'Encyclopaedia Britannica literature and author biographies — https://www.britannica.com/art/literature ; Nobel Prize, Rabindranath Tagore — https://www.nobelprize.org/prizes/literature/1913/tagore/') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2476','literature','Genres','hard','classic','What is an unreliable narrator?','["A narrator whose account may be incomplete, biased, or misleading","A narrator who appears in every chapter","A narrator who tells a story using only numbers","A narrator who cannot describe any event"]'::jsonb,'A narrator whose account may be incomplete, biased, or misleading','An unreliable narrator''s perspective cannot be accepted as fully accurate without question.',10,2,array['genres'],'en',true,'Encyclopaedia Britannica literature and author biographies — https://www.britannica.com/art/literature ; Nobel Prize, Rabindranath Tagore — https://www.nobelprize.org/prizes/literature/1913/tagore/') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2477','food','Food science','medium','classic','What is the Maillard reaction?','["Browning caused by reactions between amino compounds and reducing sugars","The freezing of water inside a food","The separation of oil and water into layers","The conversion of starch into fiber"]'::jsonb,'Browning caused by reactions between amino compounds and reducing sugars','The Maillard reaction creates browned flavors when amino compounds and reducing sugars react under heat.',10,2,array['food science'],'en',true,'USDA Food Safety and Inspection Service — https://www.fsis.usda.gov/food-safety ; FoodSafety.gov — https://www.foodsafety.gov/ ; Encyclopaedia Britannica, Food — https://www.britannica.com/topic/food') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2478','food','Food preservation','medium','classic','What is curing used for in food preparation?','["Preserving food with methods such as salting, smoking, or drying","Browning sugar by heating it","Mixing oil into water as small droplets","Cooking food in a sealed bag at a controlled temperature"]'::jsonb,'Preserving food with methods such as salting, smoking, or drying','Curing uses salt and sometimes smoke, sugar, or drying to preserve or flavor foods.',10,2,array['food preservation'],'en',true,'USDA Food Safety and Inspection Service — https://www.fsis.usda.gov/food-safety ; FoodSafety.gov — https://www.foodsafety.gov/ ; Encyclopaedia Britannica, Food — https://www.britannica.com/topic/food') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2479','food','Cooking methods','medium','classic','What does sous-vide cooking involve?','["Cooking food sealed in a bag in a temperature-controlled water bath","Heating food briefly in boiling water and then cooling it","Cooking food over an open flame without a pan","Drying food in direct sunlight only"]'::jsonb,'Cooking food sealed in a bag in a temperature-controlled water bath','Sous-vide cooks sealed food in a carefully controlled water bath, often at a relatively steady temperature.',10,2,array['cooking methods'],'en',true,'USDA Food Safety and Inspection Service — https://www.fsis.usda.gov/food-safety ; FoodSafety.gov — https://www.foodsafety.gov/ ; Encyclopaedia Britannica, Food — https://www.britannica.com/topic/food') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
