insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2487','food','Food safety','hard','classic','Why should raw meat and ready-to-eat foods be kept separate?','["To reduce the risk of harmful microbes transferring to foods eaten without further cooking","To make raw meat cook more quickly","To prevent vegetables from absorbing water","To allow every food to reach room temperature"]'::jsonb,'To reduce the risk of harmful microbes transferring to foods eaten without further cooking','Keeping raw foods separate helps prevent pathogens from contaminating foods that may not be cooked again.',10,2,array['food safety'],'en',true,'USDA Food Safety and Inspection Service — https://www.fsis.usda.gov/food-safety ; FoodSafety.gov — https://www.foodsafety.gov/ ; Encyclopaedia Britannica, Food — https://www.britannica.com/topic/food') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
