insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2503','arts','Painting','medium','classic','What does plein air refer to in painting?','["Painting outdoors, often directly from observation","Applying paint thickly so brushstrokes remain raised","Painting on wet plaster so pigment bonds with a wall","Printing an image from a carved wooden block"]'::jsonb,'Painting outdoors, often directly from observation','Plein air painting is made outdoors, allowing the artist to work from the landscape and changing light directly.',10,2,array['painting'],'en',true,'Tate Art Terms — https://www.tate.org.uk/art/art-terms ; The Metropolitan Museum of Art, Heilbrunn Timeline of Art History — https://www.metmuseum.org/toah/') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2504','arts','Printmaking','medium','classic','What is lithography based on?','["The repulsion of oil-based material and water on a flat printing surface","Ink transferring only from raised wooden areas","Carving deep grooves into a metal plate to hold ink","Pasting paper scraps onto a canvas"]'::jsonb,'The repulsion of oil-based material and water on a flat printing surface','Lithography uses a planographic surface and the principle that grease and water repel one another.',10,2,array['printmaking'],'en',true,'Tate Art Terms — https://www.tate.org.uk/art/art-terms ; The Metropolitan Museum of Art, Heilbrunn Timeline of Art History — https://www.metmuseum.org/toah/') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
