insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2506','arts','Printmaking','medium','classic','What is a defining feature of etching as an intaglio process?','["Incised lines hold ink below the plate''s surface","Ink is applied only to raised wooden edges","A stencil is projected onto a wall","Pigment is mixed into wet plaster"]'::jsonb,'Incised lines hold ink below the plate''s surface','In etching, lines are bitten into a plate and hold ink for printing.',10,2,array['printmaking'],'en',true,'Tate Art Terms — https://www.tate.org.uk/art/art-terms ; The Metropolitan Museum of Art, Heilbrunn Timeline of Art History — https://www.metmuseum.org/toah/') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
