insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2508','arts','Sculpture','medium','classic','What is a maquette?','["A small preliminary model used to develop a sculpture or design","A tiny piece of colored tile in a mosaic","A drawing that records a landscape from above","A print made from an engraved plate"]'::jsonb,'A small preliminary model used to develop a sculpture or design','A maquette is a small-scale model made to plan or test a larger sculpture or design.',10,2,array['sculpture'],'en',true,'Tate Art Terms — https://www.tate.org.uk/art/art-terms ; The Metropolitan Museum of Art, Heilbrunn Timeline of Art History — https://www.metmuseum.org/toah/') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
