insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2510','arts','Art history','hard','classic','What is a readymade in modern art?','["An existing manufactured object presented as an artwork","A painting made only on wet plaster","A sculpture carved from one block of stone","A small preliminary model for a larger sculpture"]'::jsonb,'An existing manufactured object presented as an artwork','A readymade is an ordinary manufactured object selected and presented as art, a practice famously associated with Marcel Duchamp.',10,2,array['art history'],'en',true,'Tate Art Terms — https://www.tate.org.uk/art/art-terms ; The Metropolitan Museum of Art, Heilbrunn Timeline of Art History — https://www.metmuseum.org/toah/') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-2511','arts','Art history','medium','classic','Which art movement is associated with fragmented forms and multiple viewpoints?','["Cubism","Impressionism","Baroque","Neoclassicism"]'::jsonb,'Cubism','Cubist artists explored geometric forms and multiple viewpoints in a single composition.',10,2,array['art history'],'en',true,'Tate Art Terms — https://www.tate.org.uk/art/art-terms ; The Metropolitan Museum of Art, Heilbrunn Timeline of Art History — https://www.metmuseum.org/toah/') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
